func newMemoryPreference() unsafe.Pointer { return unsafe.Pointer(new(agentmemory.MemoryPreference)) }

func newNMemoryPreference(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]agentmemory.MemoryPreference, n)))
}

func ptrMemoryPreference(p unsafe.Pointer, c int32) any {
	r := (*agentmemory.MemoryPreference)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 4:
		return (*string)(unsafe.Pointer(&r.SavingMode))
	case 5:
		return &r.Version
	case 6:
		return &r.CreatedAt
	case 7:
		return &r.UpdatedAt
	}
	return nil
}

func valueMemoryPreference(p unsafe.Pointer, c int32) any {
	r := (*agentmemory.MemoryPreference)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.UserID)
	case 4:
		return string(r.SavingMode)
	case 5:
		return r.Version
	case 6:
		return r.CreatedAt
	case 7:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateMemoryPreference(ctx context.Context, p unsafe.Pointer) error {
	return (*agentmemory.MemoryPreference)(p).BeforeCreate(ctx)
}

// intIs64 fails the build where int is not 64 bits: int fields are read through *int64.
const intIs64 = unsafe.Sizeof(int(0)) - 8

var enumMemoryKind = [...]schema.EnumValue{
	{Value: `Instruction`, Label: `Instruction`, Doc: `MemoryKindInstruction is a standing rule a person wants agents to follow.`},
	{Value: `Fact`, Label: `Fact`, Doc: `MemoryKindFact is something an agent was told or worked out and should weigh, not obey.`},
	{Value: `Correction`, Label: `Correction`, Doc: `MemoryKindCorrection is what a decision on a proposal taught: what a person changed or refused, and why.`},
	{Value: `Procedure`, Label: `Procedure`},
}

